mapper.update:
UPDATE
    emp_login   
SET
    emp_pw = #{password}
WHERE
    emp_id_no = #{empIdNo}

mapper.select:
SELECT e.EMP_ID AS empId, e.NAME, e.DEPT_CODE, e.TITLE, e.EMAIL, d.DEPT_NAME, l.COM_NAME, NVL(l.IS_USED, 'N') AS IS_USED FROM emp e LEFT JOIN dept d ON e.DEPT_CODE = d.DEPT_CODE LEFT JOIN emp_login l ON TO_NUMBER(REGEXP_SUBSTR(e.emp_id, '[0-9]+$')) = l.emp_no
AND d.DEPT_NAME = #{deptName}
AND e.TITLE = #{title}
ORDER BY e.NAME

